      "content": "{\n  \"name\": \"dsh-ui-enhancer\",\n  \"version\": \"0.2.0\",\n  \"description\": \"A desktop-style workspace, wallpaper, pet, and file-reference UI for DeepSeek Harness\",\n  \"type\": \"module\",\n  \"main\": \"lib/index.js\",\n  \"types\": \"lib/index.d.ts\",\n  \"license\": \"MIT\",\n  \"author\": \"AlexYin-Tongji\",\n  \"homepage\": \"https://github.com/AlexYin-Tongji/dsh-ui-enhancer#readme\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/AlexYin-Tongji/dsh-ui-enhancer.git\"\n  },\n  \"bugs\": {\n    \"url\": \"https://github.com/AlexYin-Tongji/dsh-ui-enhancer/issues\"\n  },\n  \"keywords\": [\n    \"deepseek\",\n    \"deepseek-harness\",\n    \"dsh\",\n    \"dsh-plugin\",\n    \"plugin\",\n    \"desktop-ui\",\n    \"wallpaper\",\n    \"file-preview\"\n  ],\n  \"publishConfig\": {\n    \"access\": \"public\"\n  },\n  \"engines\": {\n    \"node\": \"^22.19.0 || >=24.0.0\"\n  },\n  \"packageManager\": \"pnpm@11.22.0\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./lib/index.d.ts\",\n      \"default\": \"./lib/index.js\"\n    },\n    \"./client\": \"./lib/client.js\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"lib/**\",\n    \"cordis.patch.yml\",\n    \"CHANGELOG.md\",\n    \"CONTRIBUTING.md\",\n    \"README.md\",\n    \"LICENSE\"\n  ],\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"platform\": \"web\",\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-runtime\",\n        \"@deepseek-ai/dsh-client-locale\",\n        \"@deepseek-ai/dsh-client-ui-slots\",\n        \"@deepseek-ai/dsh-client-ui-layout\",\n        \"@deepseek-ai/dsh-client-ui-conversation\",\n        \"@deepseek-ai/dsh-client-ui-input-trigger\",\n        \"@deepseek-ai/dsh-client-ui-settings\",\n        \"@deepseek-ai/dsh-client-ui-theme\"\n      ]\n    }\n  },\n  \"scripts\": {\n    \"build\": \"tsdown\",\n    \"typecheck\": \"tsc --noEmit\",\n    \"test\": \"vitest run\",\n    \"check\": \"pnpm run typecheck && pnpm run test && pnpm run build\",\n    \"prepublishOnly\": \"pnpm run check\",\n    \"watch\": \"tsdown --watch\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"4.0.1\",\n    \"@deepseek-ai/dsh-client-locale\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-client-runtime\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-client-ui-conversation\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-client-ui-input-trigger\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-client-ui-layout\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-client-ui-theme\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-host-webserver\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-session\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-workspace\": \"0.1.0-rc.6\",\n    \"react\": \">=18.2.0 <19.0.0\",\n    \"react-dom\": \">=18.2.0 <19.0.0\"\n  },\n  \"dependencies\": {\n    \"@linxin666/dsh-client-ui-aionui-panel\": \"0.1.20\",\n    \"@linxin666/dsh-client-ui-web-ui-settings\": \"0.1.20\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.1\",\n    \"@deepseek-ai/dsh-client-locale\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-client-runtime\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-client-ui-conversation\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-client-ui-input-trigger\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-client-ui-layout\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-client-ui-theme\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-host-webserver\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-session\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-workspace\": \"0.1.0-rc.6\",\n    \"@types/node\": \"^24.0.0\",\n    \"@types/react\": \"~18.3.1\",\n    \"@types/react-dom\": \"~18.3.1\",\n    \"lightningcss\": \"^1.30.0\",\n    \"react\": \"^18.3.1\",\n    \"react-dom\": \"^18.3.1\",\n    \"tsdown\": \"^0.15.12\",\n    \"typescript\": \"^5.8.0\",\n    \"vitest\": \"^3.2.0\"\n  }\n}\n"
