      "path": "cordis.patch.yml",
      "content": "- insert:\n    - id: ui-enhancer-web-ui-settings\n      name: '@linxin666/dsh-client-ui-web-ui-settings'\n    - id: ui-enhancer-aionui-panel\n      name: '@linxin666/dsh-client-ui-aionui-panel'\n    - id: ui-enhancer\n      name: dsh-ui-enhancer\n"
