    {
      "path": "src/index.ts",
      "content": "import type { Context } from '@deepseek-ai/cordis'\nimport type {} from '@deepseek-ai/dsh-host-webserver'\nimport type {} from '@deepseek-ai/dsh-session'\nimport type {} from '@deepseek-ai/dsh-workspace'\nimport { registerPetActivity } from './host/pet-activity.ts'\nimport { registerUiEnhancerRoutes } from './host/routes.ts'\nimport { WorkspaceFiles } from './host/workspace-files.ts'\n\n/** Host services needed by the file bridge and the companion activity route. */\nexport const inject = ['webServer', 'workspaceRegistry']\n\nexport function apply(ctx: Context): void {\n  ctx.effect(\n    () => registerPetActivity(ctx),\n    'ui-enhancer: pet activity route',\n  )\n\n  const files = new WorkspaceFiles(ctx.workspaceRegistry)\n  ctx.effect(\n    () => registerUiEnhancerRoutes(ctx, files),\n    'ui-enhancer: host file preview routes',\n  )\n}\n\nexport * from './core/contracts.ts'\n"
    },
    {
      "path": "src/client/index.ts",
      "content": "import type { ClientContext } from '@deepseek-ai/dsh-client-runtime/client'\nimport type {} from '@deepseek-ai/dsh-client-locale/client'\nimport type {} from '@deepseek-ai/dsh-client-ui-slots'\nimport type {} from '@deepseek-ai/dsh-client-ui-settings/client'\nimport type {} from '@deepseek-ai/dsh-client-ui-input-trigger/client'\nimport { createElement } from 'react'\nimport { createRoot } from 'react-dom/client'\nimport { createFileTriggerSource } from './file-trigger.ts'\nimport { dictionaries, PersonalizationPage } from './PersonalizationPage.tsx'\nimport { PetCompanion } from './PetCompanion.tsx'\nimport { PetSettingsPage } from './PetSettingsPage.tsx'\nimport { installPanelInterop } from './panel-interop.ts'\nimport { PetAppearanceController } from './pet-appearance.ts'\nimport { PetController } from './pet-controller.ts'\nimport { WallpaperController } from './wallpaper.ts'\n\nexport const inject = ['slots', 'locale', 'sessions', 'inputTriggers']\n\ninterface SettingsSectionSlots {\n  inject(name: 'settings.section', effect: () => (() => void)): () => void\n  register(\n    options: {\n      name: 'settings.section'\n      id: string\n      order: number\n      label: () => string\n      locale: 'ui-enhancer'\n      inject: () => {\n        petAppearance?: PetAppearanceController\n        pet?: PetController\n        wallpaper?: WallpaperController\n        getCapabilities?: () => { panel: boolean; pet: boolean }\n      }\n    },\n    component: any,\n  ): () => void\n}\n\nexport function apply(ctx: ClientContext): void {\n  ctx.effect(() => ctx.locale.register('ui-enhancer', dictionaries), 'ui-enhancer: dictionaries')\n\n  ctx.effect(() => installPanelInterop(), 'ui-enhancer: aionui panel interop')\n\n  const wallpaper = new WallpaperController()\n  ctx.effect(() => () => wallpaper.dispose(), 'ui-enhancer: wallpaper')\n\n  const petAppearance = new PetAppearanceController()\n  ctx.effect(() => () => petAppearance.dispose(), 'ui-enhancer: pet appearance')\n\n  // rc.6 can expose a second runtime package identity through dependency\n  // peers. The browser service still implements this exact public face.\n  const pet = new PetController(ctx.sessions as unknown as ConstructorParameters<typeof PetController>[0])\n  ctx.effect(() => () => pet.dispose(), 'ui-enhancer: pet controller')\n\n  // The local rc.6 dependency graph may contain a second ui-slots identity\n  // through runtime peers. This narrow adapter describes only the official\n  // settings.section surface used here and has no effect on runtime dispatch.\n  const settingsSlots = ctx.slots as unknown as SettingsSectionSlots\n  const t = ctx.locale.bind('ui-enhancer')\n  settingsSlots.inject('settings.section', () => {\n    const disposePersonalization = settingsSlots.register({\n      name: 'settings.section',\n      id: 'ui-enhancer-personalization',\n      order: 35,\n      label: () => t('settings.title'),\n      locale: 'ui-enhancer',\n      inject: () => ({\n        wallpaper,\n        getCapabilities: () => ({\n          panel: document.querySelector('[data-aionui-explorer-col], [data-aionui-preview-col]') !== null,\n          pet: true,\n        }),\n      }),\n    }, PersonalizationPage)\n    const disposePet = settingsSlots.register({\n      name: 'settings.section',\n      id: 'ui-enhancer-pet',\n      order: 45,\n      label: () => t('pet.settings.title'),\n      locale: 'ui-enhancer',\n      inject: () => ({ pet, petAppearance }),\n    }, PetSettingsPage)\n    return () => {\n      disposePet()\n      disposePersonalization()\n    }\n  })\n\n  ctx.effect(() => {\n    const node = document.createElement('div')\n    node.dataset.uiEnhancerPetRoot = ''\n    document.body.append(node)\n    const root = createRoot(node)\n    root.render(createElement(PetCompanion, { pet, petAppearance, t }))\n    return () => {\n      root.unmount()\n      node.remove()\n    }\n  }, 'ui-enhancer: pet companion')\n\n  ctx.effect(\n    () => ctx.inputTriggers.registerSource(createFileTriggerSource(ctx)),\n    'ui-enhancer: @file trigger',\n  )\n}\n"
    },
    {
      "path": "src/host/routes.ts",
      "content": "import { createReadStream } from 'node:fs'\nimport type { IncomingMessage, ServerResponse } from 'node:http'\nimport type { Context } from '@deepseek-ai/cordis'\nimport type {} from '@deepseek-ai/dsh-host-webserver'\nimport {\n  UI_ENHANCER_API_PATH,\n  UI_ENHANCER_RAW_PATH,\n  type ApiEnvelope,\n  type HostError,\n  type UiEnhancerRequest,\n} from '../core/contracts.ts'\nimport { isHostError, WorkspaceFiles } from './workspace-files.ts'\n\nconst REQUEST_LIMIT_BYTES = 64 * 1024\n\nexport interface ByteRange {\n  start: number\n  end: number\n}\n\n/** Parse the single byte range used by browser PDF/media viewers. */\nexport function parseByteRange(header: string | undefined, size: number): ByteRange | 'invalid' | null {\n  if (header === undefined) return null\n  const match = /^bytes=(\\d*)-(\\d*)$/.exec(header.trim())\n  if (match === null || (match[1] === '' && match[2] === '')) return null\n  const first = match[1] ?? ''\n  const last = match[2] ?? ''\n  if (first === '') {\n    const suffix = Number(last)\n    if (!Number.isSafeInteger(suffix) || suffix <= 0 || size === 0) return 'invalid'\n    return { start: Math.max(0, size - suffix), end: size - 1 }\n  }\n  const start = Number(first)\n  const requestedEnd = last === '' ? size - 1 : Number(last)\n  if (!Number.isSafeInteger(start) || !Number.isSafeInteger(requestedEnd) || size === 0 || start >= size) {\n    return 'invalid'\n  }\n  const end = Math.min(requestedEnd, size - 1)\n  return start <= end ? { start, end } : 'invalid'\n}\n\nfunction respondJson(res: ServerResponse, body: ApiEnvelope<unknown>, status = 200): void {\n  res.writeHead(status, {\n    'content-type': 'application/json; charset=utf-8',\n    'cache-control': 'no-store',\n    'x-content-type-options': 'nosniff',\n  })\n  res.end(JSON.stringify(body))\n}\n\nfunction fail(res: ServerResponse, code: HostError['code'], message: string, status = 400): void {\n  respondJson(res, { ok: false, error: { code, message } }, status)\n}\n\nfunction isLoopbackAddress(value: string | undefined): boolean {\n  if (value === undefined) return false\n  const normalized = value.replace(/^::ffff:/, '')\n  return normalized === '127.0.0.1' || normalized === '::1'\n}\n\nasync function parseRequest(req: IncomingMessage): Promise<UiEnhancerRequest | null> {\n  const chunks: Buffer[] = []\n  let total = 0\n  for await (const chunk of req) {\n    const data = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk)\n    total += data.length\n    if (total > REQUEST_LIMIT_BYTES) return null\n    chunks.push(data)\n  }\n  try {\n    const value = JSON.parse(Buffer.concat(chunks).toString('utf8')) as unknown\n    return validateRequest(value) ? value : null\n  } catch {\n    return null\n  }\n}\n\nexport function validateRequest(value: unknown): value is UiEnhancerRequest {\n  if (typeof value !== 'object' || value === null) return false\n  const request = value as Record<string, unknown>\n  switch (request.action) {\n    case 'workspaces.list':\n      return true\n    case 'files.list':\n      return typeof request.root === 'string'\n        && (request.path === undefined || typeof request.path === 'string')\n    case 'files.search':\n      return typeof request.root === 'string' && typeof request.query === 'string'\n    case 'files.read':\n      return typeof request.root === 'string' && typeof request.path === 'string'\n    default:\n      return false\n  }\n}\n\n/** Register the JSON bridge and byte-stream route on the shared DSH server. */\nexport function registerUiEnhancerRoutes(ctx: Context, files: WorkspaceFiles): () => void {\n  const api = async (req: IncomingMessage, res: ServerResponse): Promise<void> => {\n    if (!isLoopbackAddress(req.socket.remoteAddress)) {\n      fail(res, 'bad-request', 'Loopback requests only', 403)\n      return\n    }\n    if (req.method !== 'POST') {\n      res.writeHead(405, { allow: 'POST' })\n      res.end()\n      return\n    }\n    const contentType = req.headers['content-type']?.toLowerCase() ?? ''\n    if (!contentType.startsWith('application/json')) {\n      fail(res, 'bad-request', 'Content-Type must be application/json', 415)\n      return\n    }\n    const request = await parseRequest(req)\n    if (request === null) {\n      fail(res, 'bad-request', 'Malformed request')\n      return\n    }\n    try {\n      let result: unknown\n      switch (request.action) {\n        case 'workspaces.list':\n          result = files.summaries()\n          break\n        case 'files.list':\n          result = await files.list(request.root, request.path ?? '')\n          break\n        case 'files.search':\n          result = await files.search(request.root, request.query)\n          break\n        case 'files.read':\n          result = await files.read(request.root, request.path)\n          break\n      }\n      if (isHostError(result)) {\n        const status = result.code === 'workspace-unknown' || result.code === 'path-outside-root'\n          ? 403\n          : result.code === 'not-found' ? 404 : 400\n        respondJson(res, { ok: false, error: result }, status)\n        return\n      }\n      respondJson(res, { ok: true, value: result })\n    } catch (caught) {\n      ctx.logger.warn(`ui-enhancer host request failed: ${String(caught)}`)\n      fail(res, 'internal', 'Host request failed', 500)\n    }\n  }\n\n  const raw = async (req: IncomingMessage, res: ServerResponse): Promise<void> => {\n    if (!isLoopbackAddress(req.socket.remoteAddress)) {\n      fail(res, 'bad-request', 'Loopback requests only', 403)\n      return\n    }\n    if (req.method !== 'GET' && req.method !== 'HEAD') {\n      res.writeHead(405, { allow: 'GET, HEAD' })\n      res.end()\n      return\n    }\n    const url = new URL(req.url ?? UI_ENHANCER_RAW_PATH, 'http://localhost')\n    const root = url.searchParams.get('root') ?? ''\n    const path = url.searchParams.get('path') ?? ''\n    const result = await files.raw(root, path)\n    if (isHostError(result)) {\n      const status = result.code === 'workspace-unknown' || result.code === 'path-outside-root'\n        ? 403\n        : result.code === 'not-found' ? 404 : 400\n      respondJson(res, { ok: false, error: result }, status)\n      return\n    }\n    const etag = `W/\\\"${result.size}-${Math.floor(result.mtime)}\\\"`\n    if (req.headers['if-none-match'] === etag) {\n      res.writeHead(304, { etag })\n      res.end()\n      return\n    }\n    const range = parseByteRange(req.headers.range, result.size)\n    if (range === 'invalid') {\n      res.writeHead(416, {\n        'content-range': `bytes */${result.size}`,\n        'accept-ranges': 'bytes',\n        etag,\n      })\n      res.end()\n      return\n    }\n    const responseRange = range ?? { start: 0, end: Math.max(0, result.size - 1) }\n    const headers: Record<string, string | number> = {\n      'content-type': result.mime,\n      'content-length': result.size === 0 ? 0 : responseRange.end - responseRange.start + 1,\n      'cache-control': 'no-cache',\n      'content-disposition': 'inline',\n      'x-content-type-options': 'nosniff',\n      'accept-ranges': 'bytes',\n      'content-security-policy': \"sandbox; default-src 'none'; style-src 'unsafe-inline'; img-src data: blob:\",\n      etag,\n    }\n    if (range !== null) headers['content-range'] = `bytes ${range.start}-${range.end}/${result.size}`\n    res.writeHead(range === null ? 200 : 206, headers)\n    if (req.method === 'HEAD') {\n      res.end()\n      return\n    }\n    const stream = range === null\n      ? createReadStream(result.path)\n      : createReadStream(result.path, { start: range.start, end: range.end })\n    stream.on('error', (caught) => {\n      ctx.logger.warn(`ui-enhancer raw stream failed: ${String(caught)}`)\n      if (!res.headersSent) fail(res, 'read-failed', 'Cannot stream file', 500)\n      else res.destroy(caught as Error)\n    })\n    stream.pipe(res)\n  }\n\n  const disposers = [\n    ctx.webServer.register({ kind: 'exact', path: UI_ENHANCER_API_PATH, handler: api }),\n    ctx.webServer.register({ kind: 'exact', path: UI_ENHANCER_RAW_PATH, handler: raw }),\n  ]\n  return () => {\n    for (const dispose of disposers) dispose()\n  }\n}\n"
