      "path": "src/host/pet-activity.ts",
      "content": "import type { IncomingMessage, ServerResponse } from 'node:http'\nimport type { Context } from '@deepseek-ai/cordis'\nimport type { Session, SessionEvent } from '@deepseek-ai/dsh-session'\nimport type { WebRoute } from '@deepseek-ai/dsh-host-webserver'\n\nexport const PET_ACTIVITY_API_PATH = '/api/ui-enhancer/pet-state'\nexport const PET_ACTIVITY_SESSION_LIMIT = 8\nexport const PET_COMPLETION_EVENT_LIMIT = 128\nexport const PET_SETTLED_PHASE_TTL_MS = 6_000\nexport const PET_SESSION_DETAIL_MAX = 200\n\nexport type PetActivityPhase = 'idle' | 'waiting' | 'thinking' | 'tool' | 'review' | 'done' | 'failed'\n\nexport interface PetActivitySessionView {\n  sessionId: string\n  phase: PetActivityPhase\n  bubble: string\n  /** Recent conversation detail: tool invocation or reply snippet. */\n  detail: string\n  updatedAt: number\n}\n\nexport interface PetActivityView {\n  phase: PetActivityPhase\n  bubble: string\n  sessions: PetActivitySessionView[]\n  /** Oldest to newest; IDs stay stable across polls for client-side deduplication. */\n  completedEventIds: string[]\n}\n\ninterface SessionActivity {\n  sessionId: string\n  topLevel: boolean\n  phase: PetActivityPhase\n  bubble: string\n  detail: string\n  updatedAt: number\n  activeTools: Set<string>\n  stepHadFailure: boolean\n}\n\nfunction compactToolName(value: string): string {\n  const compact = value.replace(/\\s+/g, ' ').trim() || '工具'\n  return compact.length <= 24 ? compact : `${compact.slice(0, 21)}...`\n}\n\n/** Append one text delta to the trailing detail window. */\nfunction appendDetail(previous: string, delta: string): string {\n  const combined = (previous + delta).replace(/\\s+/g, ' ').trim()\n  if (combined.length <= PET_SESSION_DETAIL_MAX) return combined\n  return combined.slice(combined.length - PET_SESSION_DETAIL_MAX)\n}\n\n/** Detail line for a tool call: compact name plus a short argument snippet. */\nfunction toolDetail(name: string, rawArguments: string): string {\n  const compact = compactToolName(name)\n  const argumentsSnippet = rawArguments.replace(/\\s+/g, ' ').trim().slice(0, 80)\n  return argumentsSnippet === '' ? `调用 ${compact}` : `调用 ${compact} · ${argumentsSnippet}`\n}\n\nfunction isSettled(activity: SessionActivity, nowMs: number): boolean {\n  if (activity.phase === 'idle') return true\n  return (activity.phase === 'done' || activity.phase === 'failed')\n    && nowMs - activity.updatedAt >= PET_SETTLED_PHASE_TTL_MS\n}\n\n/** In-memory projection of official Harness session events for the desktop companion. */\nexport class PetActivityTracker {\n  private readonly activity = new Map<string, SessionActivity>()\n  private readonly completedEventIds: string[] = []\n  private readonly completedEventSet = new Set<string>()\n\n  accept(session: Session, event: SessionEvent, nowMs = Date.now()): void {\n    switch (event.type) {\n      case 'turn/start': {\n        const activity = this.activityOf(session, nowMs)\n        activity.activeTools.clear()\n        activity.stepHadFailure = false\n        activity.detail = ''\n        this.commit(activity, 'waiting', '准备开始', nowMs)\n        break\n      }\n      case 'step/start': {\n        const activity = this.activityOf(session, nowMs)\n        activity.activeTools.clear()\n        activity.stepHadFailure = false\n        activity.detail = ''\n        this.commit(activity, 'waiting', '等待模型响应', nowMs)\n        break\n      }\n      case 'assistant/chunk': {\n        if (event.data.chunk.type === 'reasoning-delta' && event.data.chunk.text.length > 0) {\n          this.commit(this.activityOf(session, nowMs), 'thinking', '正在思考', nowMs)\n        } else if (event.data.chunk.type === 'text-delta' && event.data.chunk.text.length > 0) {\n          const activity = this.activityOf(session, nowMs)\n          // A tool line followed by prose starts a fresh run of text detail.\n          const previous = activity.detail.startsWith('调用 ') ? '' : activity.detail\n          activity.detail = appendDetail(previous, event.data.chunk.text)\n          this.commit(activity, 'review', '整理回复中', nowMs)\n        }\n        break\n      }\n      case 'assistant/message':\n        this.commit(this.activityOf(session, nowMs), 'review', '整理回复中', nowMs)\n        break\n      case 'tool/call': {\n        const activity = this.activityOf(session, nowMs)\n        activity.activeTools.add(String(event.data.callId))\n        activity.detail = toolDetail(event.data.name, event.data.arguments)\n        this.commit(activity, 'tool', `正在使用 ${compactToolName(event.data.name)}`, nowMs)\n        break\n      }\n      case 'tool/result': {\n        const activity = this.activityOf(session, nowMs)\n        activity.activeTools.delete(String(event.data.message.source.callId))\n        activity.stepHadFailure ||= event.data.error !== undefined\n          || event.data.message.content[0]?.isError === true\n        if (activity.activeTools.size > 0) {\n          this.commit(activity, 'tool', `还有 ${activity.activeTools.size} 个工具运行中`, nowMs)\n        } else if (activity.stepHadFailure) {\n          this.commit(activity, 'failed', '工具执行失败', nowMs)\n        } else {\n          this.commit(activity, 'thinking', '处理工具结果', nowMs)\n        }\n        break\n      }\n      case 'turn/end': {\n        const activity = this.activityOf(session, nowMs)\n        activity.activeTools.clear()\n        switch (event.data.reason.kind) {\n          case 'completed':\n            if (activity.topLevel) {\n              this.rememberCompletion(`${String(session.id)}:${event.data.turn}`)\n            }\n            this.commit(activity, 'done', '完成啦', nowMs)\n            break\n          case 'error':\n            this.commit(activity, 'failed', '执行失败', nowMs)\n            break\n          case 'max-tokens':\n            this.commit(activity, 'failed', '达到输出上限', nowMs)\n            break\n          case 'interrupted':\n            this.commit(activity, 'failed', '执行意外中断', nowMs)\n            break\n          case 'blocked':\n            this.commit(activity, 'waiting', '等待继续', nowMs)\n            break\n          case 'aborted':\n            this.commit(activity, 'idle', '', nowMs)\n            break\n          default:\n            this.commit(activity, 'idle', '', nowMs)\n        }\n        break\n      }\n      default:\n        break\n    }\n  }\n\n  forget(session: Session): void {\n    this.activity.delete(String(session.id))\n  }\n\n  snapshot(nowMs = Date.now()): PetActivityView {\n    const current = [...this.activity.values()]\n      .reverse()\n      .filter((entry) => !isSettled(entry, nowMs))\n    const display = current[0]\n    const sessions = current\n      .filter((entry) => entry.topLevel && entry.bubble !== '')\n      .slice(0, PET_ACTIVITY_SESSION_LIMIT)\n      .map(({ sessionId, phase, bubble, detail, updatedAt }) => ({ sessionId, phase, bubble, detail, updatedAt }))\n    return {\n      phase: display?.phase ?? 'idle',\n      bubble: display?.bubble ?? '',\n      sessions,\n      completedEventIds: [...this.completedEventIds],\n    }\n  }\n\n  private activityOf(session: Session, nowMs: number): SessionActivity {\n    const sessionId = String(session.id)\n    let activity = this.activity.get(sessionId)\n    if (activity === undefined) {\n      activity = {\n        sessionId,\n        topLevel: session.header.origin !== 'subagent',\n        phase: 'idle',\n        bubble: '',\n        detail: '',\n        updatedAt: nowMs,\n        activeTools: new Set(),\n        stepHadFailure: false,\n      }\n    } else {\n      activity.topLevel = session.header.origin !== 'subagent'\n    }\n    return activity\n  }\n\n  private commit(\n    activity: SessionActivity,\n    phase: PetActivityPhase,\n    bubble: string,\n    nowMs: number,\n  ): void {\n    activity.phase = phase\n    activity.bubble = bubble\n    activity.updatedAt = nowMs\n    this.activity.delete(activity.sessionId)\n    this.activity.set(activity.sessionId, activity)\n    while (this.activity.size > PET_ACTIVITY_SESSION_LIMIT) {\n      const oldest = this.activity.keys().next().value\n      if (oldest === undefined) break\n      this.activity.delete(oldest)\n    }\n  }\n\n  private rememberCompletion(id: string): void {\n    if (this.completedEventSet.has(id)) return\n    this.completedEventIds.push(id)\n    this.completedEventSet.add(id)\n    while (this.completedEventIds.length > PET_COMPLETION_EVENT_LIMIT) {\n      const oldest = this.completedEventIds.shift()\n      if (oldest !== undefined) this.completedEventSet.delete(oldest)\n    }\n  }\n}\n\nfunction respondJson(res: ServerResponse, body: PetActivityView): void {\n  const payload = JSON.stringify(body)\n  res.writeHead(200, {\n    'content-type': 'application/json; charset=utf-8',\n    'content-length': Buffer.byteLength(payload),\n    'cache-control': 'no-store',\n    'x-content-type-options': 'nosniff',\n  })\n  res.end(payload)\n}\n\n/** Mount the event projection and its plugin-owned, read-only browser route. */\nexport function registerPetActivity(ctx: Context): () => void {\n  const tracker = new PetActivityTracker()\n  const route: WebRoute = {\n    kind: 'exact',\n    path: PET_ACTIVITY_API_PATH,\n    handler: (req: IncomingMessage, res: ServerResponse): void => {\n      if (req.method !== 'GET') {\n        res.writeHead(405, { allow: 'GET' })\n        res.end()\n        return\n      }\n      respondJson(res, tracker.snapshot())\n    },\n  }\n  const disposers = [\n    ctx.on('session/event', (session, event) => tracker.accept(session, event)),\n    ctx.on('session/disposed', (session) => tracker.forget(session)),\n    ctx.webServer.register(route),\n  ]\n  return () => {\n    for (const dispose of disposers.reverse()) dispose()\n  }\n}\n"
    },
    {
      "path": "src/host/workspace-files.ts",
      "content": "import type { Dirent } from 'node:fs'\nimport { open, readdir, realpath, stat } from 'node:fs/promises'\nimport { extname, isAbsolute, join, posix, relative, resolve, sep } from 'node:path'\nimport type { Workspace } from '@deepseek-ai/dsh-workspace'\nimport type {\n  FileEntry,\n  FileListing,\n  FileSearchHit,\n  FileSearchResult,\n  HostError,\n  TextFileContent,\n} from '../core/contracts.ts'\n\nconst TEXT_CHAR_LIMIT = 200_000\nconst TEXT_BYTE_BUDGET = TEXT_CHAR_LIMIT * 4 + 3\nconst SEARCH_HIT_LIMIT = 100\nconst SEARCH_SCAN_LIMIT = 20_000\nconst SEARCH_DEPTH_LIMIT = 32\nconst HIDDEN_TREE_DIRS = new Set(['.git'])\nconst SEARCH_IGNORED_DIRS = new Set(['.git', 'node_modules'])\n\nexport type FileResult<T> = T | HostError\n\nexport interface WorkspaceSource {\n  list(): Workspace[]\n}\n\nfunction error(code: HostError['code'], message: string): HostError {\n  return { code, message }\n}\n\nexport function isHostError(value: unknown): value is HostError {\n  return typeof value === 'object' && value !== null && typeof (value as HostError).code === 'string'\n}\n\n/** Platform-aware containment check with a path-segment boundary. */\nexport function isPathInside(root: string, candidate: string): boolean {\n  const rel = relative(root, candidate)\n  return rel === '' || (!rel.startsWith(`..${sep}`) && rel !== '..' && !isAbsolute(rel))\n}\n\nfunction portableRelativePath(value: string): string {\n  return value.split(sep).join('/')\n}\n\nfunction normalizedSearchPath(value: string): string {\n  const normalized = posix.normalize(value.replaceAll('\\\\', '/'))\n  if (normalized === '.') return ''\n  return normalized.replace(/^\\/+|\\/+$/g, '').toLocaleLowerCase()\n}\n\nfunction searchMatchRank(name: string, path: string, needle: string): number | undefined {\n  if (!name.includes(needle) && !path.includes(needle)) return undefined\n  if (path === needle) return 0\n  if (name === needle) return 1\n  if (name.startsWith(needle)) return 2\n  if (name.includes(needle)) return 3\n  if (path.startsWith(needle)) return 4\n  const offset = path.indexOf(needle)\n  return offset > 0 && path[offset - 1] === '/' ? 5 : 6\n}\n\nfunction containsGitSegment(value: string): boolean {\n  return value.split(/[\\\\/]/).some((part) => part.toLowerCase() === '.git')\n}\n\nfunction mimeForPath(path: string): string {\n  const extension = extname(path).toLowerCase()\n  const known: Record<string, string> = {\n    '.md': 'text/markdown',\n    '.mdx': 'text/markdown',\n    '.txt': 'text/plain',\n    '.log': 'text/plain',\n    '.json': 'application/json',\n    '.jsonl': 'application/x-ndjson',\n    '.js': 'text/javascript',\n    '.jsx': 'text/javascript',\n    '.mjs': 'text/javascript',\n    '.cjs': 'text/javascript',\n    '.ts': 'text/typescript',\n    '.tsx': 'text/typescript',\n    '.css': 'text/css',\n    '.html': 'text/html',\n    '.htm': 'text/html',\n    '.xml': 'application/xml',\n    '.yaml': 'application/yaml',\n    '.yml': 'application/yaml',\n    '.toml': 'application/toml',\n    '.csv': 'text/csv',\n    '.tsv': 'text/tab-separated-values',\n    '.py': 'text/x-python',\n    '.rs': 'text/x-rust',\n    '.go': 'text/x-go',\n    '.java': 'text/x-java-source',\n    '.c': 'text/x-c',\n    '.h': 'text/x-c',\n    '.cpp': 'text/x-c++src',\n    '.hpp': 'text/x-c++src',\n    '.sh': 'text/x-shellscript',\n    '.sql': 'application/sql',\n  }\n  return known[extension] ?? 'text/plain'\n}\n\n/** Filesystem operations restricted to a root published by WorkspaceRegistry. */\nexport class WorkspaceFiles {\n  constructor(private readonly workspaces: WorkspaceSource) {}\n\n  summaries(): Array<{ id: string; title: string; path: string }> {\n    return this.workspaces.list().map((workspace) => ({\n      id: String(workspace.id),\n      title: workspace.title,\n      path: workspace.path,\n    }))\n  }\n\n  async list(root: string, requestedPath = ''): Promise<FileResult<FileListing>> {\n    const workspaceRoot = await this.requireWorkspace(root)\n    if (isHostError(workspaceRoot)) return workspaceRoot\n    const target = await this.resolveExisting(workspaceRoot, requestedPath)\n    if (isHostError(target)) return target\n\n    let items: Dirent<string>[]\n    try {\n      items = await readdir(target, { withFileTypes: true })\n    } catch {\n      return error('not-found', `Cannot list ${requestedPath || '.'}`)\n    }\n\n    const entries = await Promise.all(items\n      .filter((entry) => !(entry.isDirectory() && HIDDEN_TREE_DIRS.has(entry.name)))\n      .map(async (entry): Promise<FileEntry> => {\n        const absolute = join(target, entry.name)\n        const rel = portableRelativePath(relative(workspaceRoot, absolute))\n        if (entry.isDirectory()) {\n          return { name: entry.name, path: rel, kind: 'directory', size: 0, mtime: 0 }\n        }\n        try {\n          const info = await stat(absolute)\n          return { name: entry.name, path: rel, kind: 'file', size: info.size, mtime: info.mtimeMs }\n        } catch {\n          return { name: entry.name, path: rel, kind: 'file', size: 0, mtime: 0 }\n        }\n      }))\n\n    entries.sort((left, right) => {\n      if (left.kind !== right.kind) return left.kind === 'directory' ? -1 : 1\n      return left.name.localeCompare(right.name, undefined, { sensitivity: 'base' })\n    })\n    return {\n      root: workspaceRoot,\n      path: portableRelativePath(relative(workspaceRoot, target)),\n      entries,\n    }\n  }\n\n  async read(root: string, requestedPath: string): Promise<FileResult<TextFileContent>> {\n    const workspaceRoot = await this.requireWorkspace(root)\n    if (isHostError(workspaceRoot)) return workspaceRoot\n    if (requestedPath === '') return error('is-directory', 'A file path is required')\n    const target = await this.resolveExisting(workspaceRoot, requestedPath)\n    if (isHostError(target)) return target\n\n    let info: Awaited<ReturnType<typeof stat>>\n    try {\n      info = await stat(target)\n    } catch {\n      return error('not-found', `Cannot read ${requestedPath}`)\n    }\n    if (!info.isFile()) return error('is-directory', `${requestedPath} is not a file`)\n\n    const handle = await open(target, 'r').catch(() => null)\n    if (handle === null) return error('read-failed', `Cannot read ${requestedPath}`)\n    try {\n      const buffer = Buffer.alloc(Math.min(info.size, TEXT_BYTE_BUDGET))\n      const { bytesRead } = await handle.read(buffer, 0, buffer.length, 0)\n      const data = buffer.subarray(0, bytesRead)\n      if (data.subarray(0, Math.min(data.length, 8_192)).includes(0)) {\n        return error('binary-file', 'Use the raw preview URL for binary files')\n      }\n      const decoded = data.toString('utf8')\n      const truncated = info.size > bytesRead || decoded.length > TEXT_CHAR_LIMIT\n      return {\n        path: portableRelativePath(relative(workspaceRoot, target)),\n        content: truncated ? decoded.slice(0, TEXT_CHAR_LIMIT) : decoded,\n        size: info.size,\n        mtime: info.mtimeMs,\n        mime: mimeForPath(requestedPath),\n        truncated,\n      }\n    } catch {\n      return error('read-failed', `Cannot read ${requestedPath}`)\n    } finally {\n      await handle.close().catch(() => undefined)\n    }\n  }\n\n  async raw(root: string, requestedPath: string): Promise<FileResult<{ path: string; size: number; mtime: number; mime: string }>> {\n    const workspaceRoot = await this.requireWorkspace(root)\n    if (isHostError(workspaceRoot)) return workspaceRoot\n    if (requestedPath === '' || containsGitSegment(requestedPath)) {\n      return error('path-outside-root', 'The requested path is not available')\n    }\n    const target = await this.resolveExisting(workspaceRoot, requestedPath)\n    if (isHostError(target)) return target\n    try {\n      const info = await stat(target)\n      if (!info.isFile()) return error('is-directory', `${requestedPath} is not a file`)\n      return {\n        path: target,\n        size: info.size,\n        mtime: info.mtimeMs,\n        mime: rawMimeForPath(requestedPath),\n      }\n    } catch {\n      return error('not-found', `Cannot read ${requestedPath}`)\n    }\n  }\n\n  async search(root: string, rawQuery: string): Promise<FileResult<FileSearchResult>> {\n    const workspaceRoot = await this.requireWorkspace(root)\n    if (isHostError(workspaceRoot)) return workspaceRoot\n    const query = rawQuery.trim()\n    if (query === '') return { query: rawQuery, hits: [], truncated: false }\n\n    const needle = normalizedSearchPath(query)\n    if (needle === '') return { query: rawQuery, hits: [], truncated: false }\n\n    const matches: Array<{ hit: FileSearchHit; rank: number; depth: number }> = []\n    let scanned = 0\n    let scanLimitReached = false\n    let depthLimitReached = false\n    const walk = async (directory: string, depth: number): Promise<void> => {\n      if (scanLimitReached) return\n      if (depth > SEARCH_DEPTH_LIMIT) {\n        depthLimitReached = true\n        return\n      }\n      let entries: Dirent<string>[]\n      try {\n        entries = await readdir(directory, { withFileTypes: true })\n      } catch {\n        return\n      }\n      for (const entry of entries) {\n        if (scanned >= SEARCH_SCAN_LIMIT) {\n          scanLimitReached = true\n          return\n        }\n        scanned += 1\n        if (entry.isDirectory() && SEARCH_IGNORED_DIRS.has(entry.name)) continue\n        const absolute = join(directory, entry.name)\n        const kind = entry.isDirectory() ? 'directory' as const : 'file' as const\n        const path = portableRelativePath(relative(workspaceRoot, absolute))\n        const normalizedPath = normalizedSearchPath(path)\n        const rank = searchMatchRank(entry.name.toLocaleLowerCase(), normalizedPath, needle)\n        if (rank !== undefined) {\n          matches.push({\n            hit: { name: entry.name, path, kind },\n            rank,\n            depth: normalizedPath.split('/').length,\n          })\n        